_CORE_SRC = '# Exact action format: {"moves": [(from_node, to_node, count), ...], "build": n_buy}\n# Payout: equal fleets serve capacity_p * demand / max(capacity_0 + capacity_1,\n# demand); otherwise the larger fleet serves min(capacity_more, demand), and\n# the smaller serves min(capacity_fewer, demand - served_more).\n# Profit = revenue - 2.0 * drones away from own base - 15.0 * drones bought.\n# Purchases use start-of-turn money; bought drones cannot move that turn.\n\nimport heapq\nimport math\nimport time\nfrom collections import deque\n\nTIME_BUDGET = 0.25\nN_TURNS = 120\nCAPACITY = 4\nUPKEEP = 2.0\nBUILD_COST = 15.0\nMAX_DRONES = 40\n\n\ndef served(own, opponent, demand):\n    """The exact revenue rule, including the zero-demand case."""\n    if demand <= 0.0 or own <= 0:\n        return 0.0\n    if own == opponent:\n        return own * CAPACITY * demand / max(\n            (own + opponent) * CAPACITY, demand\n        )\n    if own > opponent:\n        return min(own * CAPACITY, demand)\n    return min(own * CAPACITY, max(0.0, demand - opponent * CAPACITY))\n\n\ndef score_at(own, opponent, demand):\n    return served(own, opponent, demand) - served(opponent, own, demand)\n\n\ndef preprocess_map(n, edges):\n    adjacency = [[] for _ in range(n)]\n    for u, v in edges:\n        adjacency[u].append(v)\n        adjacency[v].append(u)\n    for row in adjacency:\n        row.sort()\n    distances = []\n    for source in range(n):\n        d = [n + 1] * n\n        d[source] = 0\n        queue = deque([source])\n        while queue:\n            u = queue.popleft()\n            for v in adjacency[u]:\n                if d[v] == n + 1:\n                    d[v] = d[u] + 1\n                    queue.append(v)\n        distances.append(d)\n    return adjacency, distances\n\n\ndef legal_action(have, want, adjacency, distances, build, money):\n    """Closest-first transport; replay every emitted move against initial counts."""\n    n = len(have)\n    surplus = [max(0, have[i] - want[i]) for i in range(n)]\n    deficit = [max(0, want[i] - have[i]) for i in range(n)]\n    pairs = sorted(\n        (distances[s][t], s, t)\n        for s in range(n) if surplus[s]\n        for t in range(n) if deficit[t] and t != s\n    )\n    aggregated = {}\n    for distance, s, t in pairs:\n        count = min(surplus[s], deficit[t])\n        if not count:\n            continue\n        hops = [v for v in adjacency[s]\n                if distances[v][t] == distance - 1]\n        if not hops:\n            continue\n        hop = hops[0]\n        surplus[s] -= count\n        deficit[t] -= count\n        aggregated[s, hop] = aggregated.get((s, hop), 0) + count\n\n    available = list(have)\n    moves = []\n    for (s, t), count in sorted(aggregated.items()):\n        count = min(count, available[s])\n        if count > 0 and t in adjacency[s]:\n            moves.append((int(s), int(t), int(count)))\n            available[s] -= count\n    affordable = max(0, int(math.floor(max(0.0, money) / BUILD_COST)))\n    build = max(0, min(int(build), MAX_DRONES - sum(have), affordable))\n    return {"moves": moves, "build": int(build)}\n\n\nclass Strategy:\n    def __init__(self, player_id):\n        self.player_id = player_id\n        self.adjacency = None\n        self.distances = None\n        self.sums = []\n        self.samples = 0\n        self.lower = []\n        self.upper = []\n        self.last_turn = None\n        self.last_enemy = []\n        self.enemy_seen = []\n        self.previous_target = []\n        self.bad_reports = 0\n\n    def update_estimates(self, obs):\n        n = obs["n_nodes"]\n        turn = obs["turn"]\n        if self.last_turn != turn:\n            self.samples += 1\n            for i, value in enumerate(obs["demand"]):\n                self.sums[i] += value\n                # Rounding permits a 0.05-wide interval around the observation.\n                self.lower[i] = max(self.lower[i], (value - 0.05) / 1.5)\n                self.upper[i] = min(self.upper[i], (value + 0.05) / 0.5)\n            self.last_turn = turn\n        means = []\n        enemies = []\n        for i in range(n):\n            lo, hi = self.lower[i], self.upper[i]\n            empirical = (self.sums[i] + 5.5 * 2) / (self.samples + 2)\n            means.append(max(lo, min(max(lo, hi), empirical)))\n            seen = obs["opponent_drones"][i]\n            if seen is not None:\n                self.last_enemy[i] = int(seen)\n                self.enemy_seen[i] = turn\n                enemies.append(int(seen))\n            else:\n                age = turn - self.enemy_seen[i]\n                enemies.append(int(self.last_enemy[i] * (0.87 ** max(0, age))))\n        return means, enemies\n\n    def plan(self, obs, means, enemies, deadline):\n        n = obs["n_nodes"]\n        base = obs["player_base"]\n        have = obs["player_drones"]\n        remaining = N_TURNS - obs["turn"]\n        total = sum(have)\n        want = [0] * n\n        available = list(have)\n\n        # Discounted future earnings reduce the value of fragile distant plans.\n        # All actually forecast future demands are independent draws around the\n        # estimated mean; there is no demand forecast in this game\'s observation.\n        discount = 0.95\n        future_weight = [0.0] * (n + 2)\n        for distance in range(n + 2):\n            first = max(0, distance - 1)\n            future_weight[distance] = sum(\n                discount ** k for k in range(max(1, first), remaining)\n            )\n\n        max_count = total + 3\n        current_gain = [[0.0] * (max_count + 1) for _ in range(n)]\n        expected_gain = [[0.0] * (max_count + 1) for _ in range(n)]\n        for v in range(n):\n            if v == base:\n                continue\n            demands = [means[v] * (0.5 + (j + 0.5) / 10) for j in range(10)]\n            for k in range(max_count):\n                current_gain[v][k] = (\n                    score_at(k + 1, enemies[v], obs["demand"][v])\n                    - score_at(k, enemies[v], obs["demand"][v]) - UPKEEP\n                )\n                expected_gain[v][k] = sum(\n                    score_at(k + 1, enemies[v], d)\n                    - score_at(k, enemies[v], d) - UPKEEP\n                    for d in demands\n                ) / len(demands)\n\n        def value(source, target, count):\n            distance = self.distances[source][target]\n            if target == base:\n                return -UPKEEP * min(remaining, max(0, distance - 1))\n            if distance > remaining:\n                return -1e9\n            transit = UPKEEP * sum(\n                discount ** k for k in range(min(remaining, max(0, distance - 1)))\n            )\n            result = expected_gain[target][count] * future_weight[distance] - transit\n            if distance <= 1:\n                result += current_gain[target][count]\n            if source != target:\n                result -= 1.8  # hysteresis: moving must clearly improve the plan\n            if count < self.previous_target[target] and result > 0:\n                result += 0.6\n            return result\n\n        # Lazy heap updates account for all units already assigned to each target.\n        heap = []\n        for s in range(n):\n            if available[s]:\n                for v in range(n):\n                    heap.append((-value(s, v, 0), s, v, 0))\n        heapq.heapify(heap)\n        assigned = 0\n        while heap and assigned < total:\n            if time.perf_counter() >= deadline:\n                break\n            negative, source, target, version = heapq.heappop(heap)\n            if available[source] <= 0:\n                continue\n            if version != want[target]:\n                heapq.heappush(heap, (\n                    -value(source, target, want[target]),\n                    source, target, want[target]\n                ))\n                continue\n            available[source] -= 1\n            want[target] += 1\n            assigned += 1\n            if available[source]:\n                heapq.heappush(heap, (\n                    -value(source, target, want[target]),\n                    source, target, want[target]\n                ))\n\n        # If interrupted, preserve every unplanned drone in its actual location.\n        for s in range(n):\n            want[s] += available[s]\n\n        build = 0\n        if assigned == total and self.bad_reports < 2 and remaining > 20:\n            room = min(2, MAX_DRONES - total)\n            money = obs.get("player_money", 0.0)\n            extra = list(want)\n            for _ in range(room):\n                if money < BUILD_COST:\n                    break\n                best = max(\n                    (value(base, v, extra[v]) * discount, -v)\n                    for v in range(n) if v != base\n                )\n                # Investment must repay its full cost with a substantial buffer.\n                if best[0] <= BUILD_COST + 9.0:\n                    break\n                extra[-best[1]] += 1\n                money -= BUILD_COST\n                build += 1\n        return want, build\n\n    def act(self, obs):\n        start = time.perf_counter()\n        deadline = start + max(0.0, 0.58 * TIME_BUDGET)\n        n = int(obs["n_nodes"])\n        if self.adjacency is None:\n            self.adjacency, self.distances = preprocess_map(n, obs["edges"])\n            self.sums = [0.0] * n\n            self.lower = [1.0] * n\n            self.upper = [10.0] * n\n            self.last_enemy = [0] * n\n            self.enemy_seen = [-1000] * n\n            self.previous_target = [0] * n\n        if (obs.get("n_invalid_actions_last_turn", 0) > 0\n                or not obs.get("action_format_correct_last_turn", True)):\n            self.bad_reports += 1\n        means, enemies = self.update_estimates(obs)\n        want, build = self.plan(obs, means, enemies, deadline)\n        self.previous_target = list(want)\n        return legal_action(\n            obs["player_drones"], want, self.adjacency, self.distances,\n            build, obs.get("player_money", 0.0)\n        )\n'
